import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.D1K3FKSn.js";const m=JSON.parse('{"title":"Known Issues","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/reference/issues.html"}],["meta",{"property":"og:title","content":"Known Issues | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/reference/issues.html"}],["meta",{"name":"twitter:title","content":"Known Issues | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"reference/issues.md","filePath":"reference/issues.md"}'),s={name:"reference/issues.md"};function i(n,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h1><h2 id="empty-brick-threshold-is-not-bit-depth-aware" tabindex="-1">Empty brick threshold is not bit-depth aware <a class="header-anchor" href="#empty-brick-threshold-is-not-bit-depth-aware" aria-label="Permalink to &quot;Empty brick threshold is not bit-depth aware&quot;">​</a></h2><p><code>DatasetConfig.emptyBrickThreshold</code> (default: 100) is compared against raw integer brick stats.</p><ul><li>8-bit: 100/255 ≈ 39% of range — reasonable</li><li>16-bit: 100/65535 ≈ 0.15% of range — effectively no culling</li></ul><p><strong>Fix:</strong> Normalize the threshold to 0–1 and compare against <code>(stats.max - window.min) / (window.max - window.min)</code> using the dataset&#39;s actual value range from <code>metadata.window</code>.</p><h2 id="empty-brick-culling-does-not-work-for-zarr-datasets" tabindex="-1">Empty brick culling does not work for Zarr datasets <a class="header-anchor" href="#empty-brick-culling-does-not-work-for-zarr-datasets" aria-label="Permalink to &quot;Empty brick culling does not work for Zarr datasets&quot;">​</a></h2><p>Brick stats (min/max) in the Zarr path are computed lazily during <code>assembleBrick()</code> in the worker and cached in <code>brickStatsCache</code>. The streaming manager calls <code>isBrickEmpty</code> <strong>before</strong> <code>loadBrick</code>, so <code>getBrickStats</code> always returns <code>null</code> on the first pass → <code>isBrickEmpty</code> returns <code>false</code> → all bricks are loaded regardless.</p><p>Culling only activates on re-visits via the CPU brick cache (i.e., after an eviction/reload cycle).</p><p><strong>Fix options:</strong></p><ul><li>Add a stats-only pre-pass for the coarsest Zarr LOD (fetch and scan without storing full brick data)</li><li>Or accept the limitation and document it — Zarr culling is a future optimization</li></ul><h2 id="empty-brick-threshold-cannot-be-determined-automatically-without-a-pre-pass" tabindex="-1">Empty brick threshold cannot be determined automatically without a pre-pass <a class="header-anchor" href="#empty-brick-threshold-cannot-be-determined-automatically-without-a-pre-pass" aria-label="Permalink to &quot;Empty brick threshold cannot be determined automatically without a pre-pass&quot;">​</a></h2><p>The threshold is inherently dataset-dependent (CT air vs. fluorescence background have different distributions). Automatic determination requires either:</p><ul><li>A histogram of brick max-values from the coarsest LOD (infrastructure already exists via <code>onBaseLodLoaded</code>)</li><li>Or a global stats pre-pass before streaming begins</li></ul><p>Currently the value must be set manually. A conservative normalized default (e.g. <code>0.02</code>) would be safer than the current <code>100</code>.</p>',14)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
